def icon(key):return '<svg class="icon" aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+icons[key]+'</svg>'
def button(text,url,style='secondary',symbol=None,download=False):
    return f'<a class="button {style}" href="{escape(url)}"'+(' download' if download else '')+'>'+ (icon(symbol) if symbol else '')+escape(text)+'</a>'
def links_block(items): return '<div class="downloads">'+''.join(button(t,url,'resource',ic,d) for t,url,ic,d in items)+'</div>'
def tags(items):return '<ul class="tags" aria-label="Tools">'+''.join('<li>'+escape(t)+'</li>' for t in items)+'</ul>'
def art_labels(label,subtitle):return '<div class="art-label"><strong>'+label+'</strong><span>'+subtitle+'</span></div>'
def kpis(arr):
    return '<dl class="kpis">'+''.join(f'<div><dt>{escape(label)}</dt><dd>{escape(str(val))}</dd></div>' for val,label in arr)+'</dl>'
